                <article class="directory-card">
                    <div class="directory-card-top"><?php if ($hasPhoto): ?><img class="directory-avatar" src="<?= htmlspecialchars(str_starts_with($photo,'/') ? '/yaconecta/public'.$photo : '/yaconecta/public/uploads/directorio/'.$photo) ?>" alt="Foto de <?= htmlspecialchars($fullName) ?>"><?php else: ?><div class="directory-avatar initials-avatar" aria-label="Iniciales <?= htmlspecialchars($initials) ?>"><?= htmlspecialchars($initials ?: '??') ?></div><?php endif; ?><span class="directory-status"><i></i><?= htmlspecialchars(ucfirst($c['estado'] ?? 'activo')) ?></span></div>
