                    <div class="directory-contact"><span><b>▥</b><?= htmlspecialchars($c['area'] ?? 'Área no registrada') ?></span><?php if (!empty($c['extension'])): ?><span><b>⌕</b>Ext. <?= htmlspecialchars($c['extension']) ?></span><?php endif; ?><?php if (!empty($c['email'])): ?><span class="directory-email"><b>✉</b><a href="mailto:<?= htmlspecialchars($c['email']) ?>"><?= htmlspecialchars($c['email']) ?></a></span><?php endif; ?></div>
                    <div class="directory-card-actions"><?php if (!empty($c['email'])): ?><a href="mailto:<?= htmlspecialchars($c['email']) ?>" aria-label="Enviar correo">✉</a><?php else: ?><span aria-label="Correo no registrado" title="Correo no registrado">✉</span><?php endif; ?><?php if (!empty($c['telefono'])): ?><a href="tel:<?= htmlspecialchars($c['telefono']) ?>" aria-label="Llamar">⌕</a><?php else: ?><span aria-label="Teléfono no registrado" title="Teléfono no registrado">⌕</span><?php endif; ?><button type="button" onclick="openDirectoryModal(<?= htmlspecialchars(json_encode(['name'=>$fullName,'role'=>$c['cargo'] ?? '','area'=>$c['area'] ?? '','email'=>$c['email'] ?? '','phone'=>$c['telefono'] ?? '','extension'=>$c['extension'] ?? '','initials'=>$initials], JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_TAG|JSON_HEX_AMP), ENT_QUOTES) ?>)" aria-label="Ver ficha completa">⋮</button></div>
                </article>
            <?php endforeach; ?>
