<div class="directory-modal" id="directoryModal" aria-hidden="true"><div class="directory-modal-card"><button class="directory-modal-close" type="button" onclick="closeDirectoryModal()">×</button><div class="directory-modal-avatar" id="modalAvatar"></div><h2 id="modalName"></h2><p id="modalRole"></p><span id="modalArea"></span><dl><dt>Correo institucional</dt><dd id="modalEmail"></dd><dt>Teléfono</dt><dd id="modalPhone"></dd><dt>Extensión</dt><dd id="modalExtension"></dd></dl><a id="modalEmailAction" class="directory-modal-mail">Enviar correo</a></div></div>
<script>
document.querySelectorAll('.directory-view-toggle button').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.directory-view-toggle button').forEach(b=>b.classList.toggle('active',b===button));document.getElementById('directoryCards').classList.toggle('list-view',button.dataset.view==='list')}));
function openDirectoryModal(person){document.getElementById('modalAvatar').textContent=person.initials||'??';document.getElementById('modalName').textContent=person.name;document.getElementById('modalRole').textContent=person.role;document.getElementById('modalArea').textContent=person.area;document.getElementById('modalEmail').textContent=person.email||'No registrado';document.getElementById('modalPhone').textContent=person.phone||'No registrado';document.getElementById('modalExtension').textContent=person.extension||'No registrada';const link=document.getElementById('modalEmailAction');link.href=person.email?'mailto:'+person.email:'#';link.style.display=person.email?'block':'none';const modal=document.getElementById('directoryModal');modal.classList.add('open');modal.setAttribute('aria-hidden','false')}function closeDirectoryModal(){const modal=document.getElementById('directoryModal');modal.classList.remove('open');modal.setAttribute('aria-hidden','true')}document.getElementById('directoryModal').addEventListener('click',event=>{if(event.target.id==='directoryModal')closeDirectoryModal()});
</script>
